function round(value, dp = 2) {
  if (!Number.isFinite(value)) return 0

  // Use string manipulation to extract decimal parts
  const str = value.toFixed(dp + 1)
  const isNegative = str.startsWith('-')
  const absStr = isNegative ? str.slice(1) : str
  const [whole, decimal] = absStr.split('.')

  // Get the digit at position dp (the one we're rounding)
  const decimalPad = decimal.padEnd(dp + 1, '0')
  const roundDigit = parseInt(decimalPad[dp])
  const keepDigits = decimalPad.slice(0, dp)

  // Half-away-from-zero rounding
  let result
  if (roundDigit >= 5) {
    // Round up
    const rounded = (BigInt(whole + keepDigits) + 1n).toString()
    // Reconstruct with proper decimal placement
    const paddedRounded = rounded.padStart(dp + 1, '0')
    const resultWhole = paddedRounded.slice(0, -dp) || '0'
    const resultFrac = paddedRounded.slice(-dp).padStart(dp, '0')
    result = parseFloat(resultWhole + '.' + resultFrac)
  } else {
    // Keep as is
    result = parseFloat(whole + '.' + keepDigits)
  }

  return isNegative ? -result : result
}

