### The Problem

The original implementation used `Math.min()` to clamp the day to the maximum days in the month:
```javascript
const day = date.getUTCDate() + days
return (
    String(year).padStart(4, '0') +
    '-' +
    String(month).padStart(2, '0') +
    '-' +
    String(Math.min(day, daysInMonth(year, month))).padStart(2, '0')
  )
```

This meant:
- `addDays('2026-01-31', 1)` returned `2026-01-31` instead of `2026-02-01` 
- `addDays('2026-12-31', 1)` returned `2026-12-31` instead of `2027-01-01`
- `periodEnd('2026-01-31')` returned `2026-01-31` instead of `2026-02-14`

### The Solution

I rewrote the `addDays()` function to properly handle overflow/underflow with while loops:

```javascript
export function addDays(iso, days) {
  const date = parseIsoDate(iso)
  if (!date) throw new Error('not an ISO date: ' + iso)

  let year = date.getUTCFullYear()
  let month = date.getUTCMonth() + 1
  let day = date.getUTCDate() + days

  // Handle day overflow with month and year rolls
  while (day > daysInMonth(year, month)) {
    day -= daysInMonth(year, month)
    month++
    if (month > 12) {
      month = 1
      year++
    }
  }

  // Handle day underflow with month and year rolls
  while (day <= 0) {
    month--
    if (month < 1) {
      month = 12
      year--
    }
    day += daysInMonth(year, month)
  }

  return (
    String(year).padStart(4, '0') +
    '-' +
    String(month).padStart(2, '0') +
    '-' +
    String(day).padStart(2, '0')
  )
}
```

